pub const KDE_DATA_TYPE_PMKID: u8 = 4;

/// Busca el KDE del PMKID. `None` si no está o si la clave no mide 16 bytes.
pub fn find_pmkid(key_data: &[u8]) -> Option<[u8; 16]> {
    let mut found = None;
    for_each_rsn_kde(key_data, |data_type, payload| {
        if data_type != KDE_DATA_TYPE_PMKID || found.is_some() {
            return;
        }
        if payload.len() < 16 {
            return;
        }
        let mut key = [0u8; 16];
        key.copy_from_slice(&payload[..16]);
        found = Some(key);
    });
    found
}
